// ==UserScript==
// @name         NGNL Chess Pieces
// @namespace    github.com/ngnl-theme
// @version      2.8.0
// @description  Fan-made No Game No Life piece set for Chess.com.
// @match        https://www.chess.com/*
// @match        https://chess.com/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

(function () {
  "use strict";

  const NGNL_PIECES = true;
  const NGNL_BOARD_COLORS = true;

  const PIECE_CSS = ":root {\n  --ngnl-wp: url(\"data:image/png;base64,\");\n  --ngnl-wn: url(\"data:image/png;base64,\");\n  --ngnl-wb: url(\"data:image/png;base64,\");\n  --ngnl-wr: url(\"data:image/png;base64,\");\n  --ngnl-wq: url(\"data:image/png;base64,\");\n  --ngnl-wk: url(\"data:image/png;base64,\");\n  --ngnl-bp: url(\"data:image/png;base64,\");\n  --ngnl-bn: url(\"data:image/png;base64,\");\n  --ngnl-bb: url(\"data:image/png;base64,\");\n  --ngnl-br: url(\"data:image/png;base64,\");\n  --ngnl-bq: url(\"data:image/png;base64,\");\n  --ngnl-bk: url(\"data:image/png;base64,\");\n\n  --theme-piece-set-wp: var(--ngnl-wp) !important;\n  --theme-piece-set-wn: var(--ngnl-wn) !important;\n  --theme-piece-set-wb: var(--ngnl-wb) !important;\n  --theme-piece-set-wr: var(--ngnl-wr) !important;\n  --theme-piece-set-wq: var(--ngnl-wq) !important;\n  --theme-piece-set-wk: var(--ngnl-wk) !important;\n  --theme-piece-set-bp: var(--ngnl-bp) !important;\n  --theme-piece-set-bn: var(--ngnl-bn) !important;\n  --theme-piece-set-bb: var(--ngnl-bb) !important;\n  --theme-piece-set-br: var(--ngnl-br) !important;\n  --theme-piece-set-bq: var(--ngnl-bq) !important;\n  --theme-piece-set-bk: var(--ngnl-bk) !important;\n}\n\n.piece.wp, .promotion-piece.wp, .vfx .element.wp {\n  background-image: var(--ngnl-wp) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.wn, .promotion-piece.wn, .vfx .element.wn {\n  background-image: var(--ngnl-wn) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.wb, .promotion-piece.wb, .vfx .element.wb {\n  background-image: var(--ngnl-wb) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.wr, .promotion-piece.wr, .vfx .element.wr {\n  background-image: var(--ngnl-wr) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.wq, .promotion-piece.wq, .vfx .element.wq {\n  background-image: var(--ngnl-wq) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.wk, .promotion-piece.wk, .vfx .element.wk {\n  background-image: var(--ngnl-wk) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.bp, .promotion-piece.bp, .vfx .element.bp {\n  background-image: var(--ngnl-bp) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.bn, .promotion-piece.bn, .vfx .element.bn {\n  background-image: var(--ngnl-bn) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.bb, .promotion-piece.bb, .vfx .element.bb {\n  background-image: var(--ngnl-bb) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.br, .promotion-piece.br, .vfx .element.br {\n  background-image: var(--ngnl-br) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.bq, .promotion-piece.bq, .vfx .element.bq {\n  background-image: var(--ngnl-bq) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n\n.piece.bk, .promotion-piece.bk, .vfx .element.bk {\n  background-image: var(--ngnl-bk) !important;\n  background-size: 100% 100% !important;\n  background-repeat: no-repeat !important;\n  background-position: center !important;\n}\n";

  const BOARD_URI = "data:image/png;base64,";

  const BOARD_IMAGE = 'url("' + BOARD_URI + '")';

  const BOARD_CSS =
    ':root {\n  --ngnl-board: ' + BOARD_IMAGE + ';\n' +
    '  --theme-board-style-image: var(--ngnl-board) !important;\n}\n\n' +
    "wc-chess-board, chess-board, .board, .fade-in-overlay {\n" +
    "  background-image: var(--ngnl-board) !important;\n" +
    "  background-size: 100% 100% !important;\n" +
    "  background-repeat: no-repeat !important;\n" +
    "  background-position: center !important;\n" +
    "}\n" +
    "\n";

  const CSS =
    (NGNL_PIECES ? PIECE_CSS : "") +
    (NGNL_BOARD_COLORS ? BOARD_CSS : "");

  const STYLE_ID = "ngnl-piece-set";
  const BOARD_HOSTS = "wc-chess-board, chess-board, .board, .fade-in-overlay, [class*=\"board\"]";
  const BOARD_TEXTURE = new RegExp("(chess-themes/boards/|assets-themes\\.chess\\.com/image/[^/\"]+/\\d+\\.png)");

  function install() {
    if (!CSS) return;
    let style = document.getElementById(STYLE_ID);
    if (!style) {
      style = document.createElement("style");
      style.id = STYLE_ID;
    }
    if (style.textContent !== CSS) {
      style.textContent = CSS;
    }
    const parent = document.head || document.documentElement;
    if (style.parentNode !== parent || parent.lastChild !== style) {
      parent.appendChild(style);
    }
  }

  function paintBoard(el) {
    if (!el || !el.style) return false;
    if (el.style.backgroundImage.indexOf("data:") !== -1) return false;
    el.style.setProperty("background-image", BOARD_IMAGE, "important");
    el.style.setProperty("background-size", "100% 100%", "important");
    el.style.setProperty("background-repeat", "no-repeat", "important");
    el.style.setProperty("background-position", "center", "important");
    return true;
  }

  function paintBoards() {
    if (!NGNL_BOARD_COLORS) return 0;
    let count = 0;
    try {
      const piece = document.querySelector(".piece");
      if (piece && piece.parentElement) {
        if (paintBoard(piece.parentElement)) count += 1;
      }
      const nodes = document.querySelectorAll(BOARD_HOSTS);
      for (let i = 0; i < nodes.length; i += 1) {
        const el = nodes[i];
        if (!el.style) continue;
        if (el.style.backgroundImage.indexOf("data:") !== -1) continue;
        const painted = window.getComputedStyle(el).backgroundImage;
        if (!painted || painted === "none") continue;
        if (!BOARD_TEXTURE.test(painted)) continue;
        if (paintBoard(el)) count += 1;
      }
    } catch (error) {
      return count;
    }
    return count;
  }

  function apply() {
    install();
    paintBoards();
  }

  apply();

  let queued = false;
  const observer = new MutationObserver(function () {
    if (queued) return;
    queued = true;
    setTimeout(function () {
      queued = false;
      apply();
    }, 0);
  });
  observer.observe(document.documentElement, {
    childList: true,
    subtree: true,
  });

  document.addEventListener("DOMContentLoaded", apply);
  window.NGNL_THEME = {
    version: "2.8.0",
    pieces: NGNL_PIECES,
    board: NGNL_BOARD_COLORS,
    css: CSS,
    reapply: apply,
    paintBoards: paintBoards,
    boardElement: function () {
      const piece = document.querySelector(".piece");
      return piece ? piece.parentElement : null;
    },
  };
  console.info("[NGNL Theme] v2.8.0 pieces=" + NGNL_PIECES + " board=" + NGNL_BOARD_COLORS);
})();
